local Navigator = require(script.Navigator)
local bindablefunc: BindableFunction = script.Parent.Parent.BindableFunction
local module = {}
module.__index = module

function module.new(vm, v)
    local self = {}
    local mt = {
        _openCallbacks = nil,
        _closeCallbacks = nil,

        _name = v,
        _belong = vm,

        _view = nil,
        _content = nil,

        _getVMS = function(self, vm)
            local vms = bindablefunc:Invoke("_getViewModelScript", vm)
            return vms
        end,
        _getView = function(self)
            if self._view then
                return self._view
            end
            local vms = self:_getVMS(vm)
            if vms then
                if vms:FindFirstChild("View") and vms.View:FindFirstChild(v) then
                    self._view = require(vms.View[v])
                    return self._view
                end
            end
        end,
        _getContent = function(self)
            if self._content then
                return self._content
            end
            local view = self:_getView()
            if view then
                local content = view:GetContent()
                self._content = content
                return self._content
            end
        end,
        _getTransition = function(self, transitionType)
            local view = self:_getView()
            if view then
                if transitionType == "In" then
                    return view.ApplyTransitionIn and function(...)
                        return view:ApplyTransitionIn(...)
                    end
                elseif transitionType == "Out" then
                    return view.ApplyTransitionOut and function(...)
                        return view:ApplyTransitionOut(...)
                    end
                end
            end
        end
    }

    for i, v in pairs(module) do
        mt[i] = v
    end

    setmetatable(self, {
        __index = function(t, k)
            if mt[k] ~= nil then
                return mt[k]
            end
            local value = rawget(t, k)
            return value
        end,
    })

    self._navigator = Navigator.new(function()
        return self:_getView()
    end, function()
        return self:_getContent()
    end, function(transitionType)
        return self:_getTransition(transitionType)
    end)
    return self
end

function module:Pop(panel, ...)
    return self._navigator:Pop(panel, ...)
end

function module:Push(panel, ...)
    return self._navigator:Push(panel, ...)
end

function module:Show(panel, ...)
    return self._navigator:Show(panel, ...)
end

function module:Hide(panel, ...)
    return self._navigator:Hide(panel, ...)
end

function module:Clean(...)
    return self._navigator:Clean(...)
end

return module